import React, { useContext, useEffect, useRef, useState } from "react";
import { CartContext } from "../context/cartContext";
import { useTranslation } from "gatsby-plugin-react-i18next";

declare global {
  interface Window {
    paypal: any;
  }
}

interface PayPalActions {
  order: {
    create: (data: Record<string, unknown>) => Promise<string>;
    capture: () => Promise<PayPalOrderDetails>;
  };
}

interface PayPalOrderDetails {
  payer: {
    name: {
      given_name: string;
    };
  };
}

interface PayPalButtonProps {
  customerName: string;
  customerEmail: string;
  customerPhone: string;
  onTransactionComplete: (
    orderDetails: string,
    totalAmount: string,
    customerPhone: string,
    customerName: string,
    customerEmail: string
  ) => Promise<void>;
}

const PayPalButton: React.FC<PayPalButtonProps> = ({
  customerName,
  customerEmail,
  customerPhone,
  onTransactionComplete,
}) => {
  const cartContext = useContext(CartContext);
  const { cart } = cartContext || { cart: [] };
  const total = cart
    .reduce((sum, item) => sum + item.price * item.quantity, 0)
    .toFixed(2);

  const paypalRef = useRef<HTMLDivElement | null>(null);
  const [sdkReady, setSdkReady] = useState(false);
  const { t } = useTranslation();

  useEffect(() => {
    const addPayPalScript = async () => {
      if (window.paypal) {
        setSdkReady(true);
        return;
      }

      const script = document.createElement("script");
      script.src =
        "https://www.paypal.com/sdk/js?client-id=AXU-5AjmWPC6v4kng-gJw3qc0Jkjz4KjUvydFAS_1kURgM0QurxRTFMtcot2WyTRGzpo5HD6It0OAwIr&currency=CAD";
      script.async = true;
      script.onload = () => setSdkReady(true);
      script.onerror = () => console.error("Error al cargar el SDK de PayPal");
      document.body.appendChild(script);
    };

    addPayPalScript();

    return () => {
      if (paypalRef.current) {
        paypalRef.current.innerHTML = "";
      }
    };
  }, []);

  useEffect(() => {
    if (sdkReady && paypalRef.current) {
      paypalRef.current.innerHTML = "";

      try {
        window.paypal
          .Buttons({
            createOrder: (_data: unknown, actions: PayPalActions) => {
              return actions.order.create({
                purchase_units: [{ amount: { value: total } }],
              });
            },
            onApprove: async (_data: unknown, actions: PayPalActions) => {
              // const details = await actions.order.capture();
              const orderDetails = cart
                .map(
                  (item) =>
                    `${item.name} | ${t("cart.quantity")}: ${item.quantity} | ${t("cart.price")}: ${(
                      item.price * item.quantity
                    ).toFixed(2)} $`
                )
                .join("\n");

              await onTransactionComplete(
                orderDetails,
                total,
                customerName,
                customerEmail,
                customerPhone
              );
            },
            onError: (err: unknown) => console.error("Error en PayPal:", err),
          })
          .render(paypalRef.current);
      } catch (error) {
        console.error("Error al renderizar PayPal:", error);
      }
    }
  }, [sdkReady, total]); 

  return <div ref={paypalRef} id="paypal-button-container"></div>;
};

export default PayPalButton;
